-- Imports questions and inferred numeric ratings from LEARNING_HISTORY.md.
-- Answer prose/evidence is deliberately not written to PostgreSQL.
-- Questions are inactive until explicitly reviewed and activated.
-- Safe to rerun: existing topics/subtopics/questions and question-linked answers are retained.
BEGIN;

-- Add only the broad subtopic categories used by this import.
INSERT INTO subtopics (topic_id, slug, name, is_active)
SELECT t.id, v.slug, v.name, true
FROM (VALUES
    ('rest_api', 'pagination', 'Pagination'),
    ('data_engineering', 'data_pipelines', 'Data Pipelines'),
    ('rest_api', 'fundamentals', 'Fundamentals'),
    ('postgresql', 'transactions', 'Transactions'),
    ('python', 'concurrency', 'Concurrency'),
    ('testing', 'assertions', 'Assertions'),
    ('postgresql', 'querying', 'Querying'),
    ('redis', 'caching', 'Caching'),
    ('kafka', 'fundamentals', 'Fundamentals'),
    ('kafka', 'consumers', 'Consumers'),
    ('python', 'fundamentals', 'Fundamentals'),
    ('ai', 'retrieval', 'Retrieval'),
    ('python', 'language_basics', 'Language Basics'),
    ('data_engineering', 'data_quality', 'Data Quality'),
    ('postgresql', 'performance', 'Performance'),
    ('design_patterns', 'creational', 'Creational'),
    ('design_patterns', 'fundamentals', 'Fundamentals'),
    ('design_patterns', 'structural', 'Structural'),
    ('design_patterns', 'behavioral', 'Behavioral'),
    ('airflow', 'fundamentals', 'Fundamentals'),
    ('airflow', 'reliability', 'Reliability')
) AS v(topic_slug, slug, name)
JOIN topics t ON t.slug = v.topic_slug
ON CONFLICT (topic_id, slug) DO NOTHING;

-- Add all 87 historical questions as inactive legacy questions.
INSERT INTO questions (topic_id, subtopic_id, text, difficulty, is_active)
SELECT t.id, s.id, v.question_text, v.difficulty, false
FROM (VALUES
    ('rest_api', 'pagination', 'В горния пример, ако изпратим само първата заявка, колко клиента ще получим и как разбираме, че има още?', 3),
    ('rest_api', 'pagination', 'след обработване на страница 2 отговорът съдържа `next_page: 3`. Каква заявка следва и при каква стойност на next_page приключваме?', 3),
    ('rest_api', 'pagination', 'API има 250 клиента, връща по 100 на страница. Първите 100 вече са записани в базата, но извличането на втората страница се проваля. Ако започнем от първата страница и отново добавим нейните записи, какъв проблем може да възникне?', 3),
    ('data_engineering', 'data_pipelines', 'клиент с ID 42 сменя username от ivan_old на ivan_new. Ако разпознаваме клиентите единствено по username, какъв проблем може да възникне при следващото зареждане?', 4),
    ('data_engineering', 'data_pipelines', 'в базата клиент ID 42 вече има новия си адрес от 11:00. Забавено изпълнение по-късно доставя стария му адрес от 10:00. Ако винаги обновяваме съществуващия запис, какъв проблем ще възникне и по какъв критерий бихме решили дали да приемем пристигналите данни?', 4),
    ('data_engineering', 'data_pipelines', 'две различни промени за един клиент имат еднакъв updated_at, защото източникът записва времето само до секунда. Достатъчно ли е това поле, за да определим коя промяна е по-нова?', 4),
    ('rest_api', 'fundamentals', 'източникът гарантира, че всяка промяна за даден клиент увеличава неговата версия. В базата пазим версия 18, а по-късно пристига версия 17 със същия updated_at. Кое състояние запазваме и защо?', 4),
    ('rest_api', 'pagination', 'трябва ли да отбележим една страница като обработена преди или след успешния запис на нейните данни в базата, и какъв е рискът, ако го направим преди?', 4),
    ('postgresql', 'transactions', 'какво ще се случи с вече записаните клиенти, ако записът е идемпотентен?', 4),
    ('rest_api', 'pagination', 'кои ID ще върне страница 2 и кой клиент ще пропуснем?', 4),
    ('python', 'concurrency', 'ако управляваме заявките с един event loop в една нишка, а една задача започне дълго изчисление, без да отстъпва управлението, ще могат ли останалите задачи в този loop да продължат през това време?', 3),
    ('python', 'concurrency', 'при един event loop и една нишка задача чака отговор от API по асинхронен начин. Може ли друга задача в същата нишка да изпрати следващ батч, преди първият отговор да е пристигнал?', 3),
    ('python', 'concurrency', 'в примера с изпратени A и B, ако отговорът за B пристигне първи, необходимо ли е да чакаме отговора за A, за да обработим B, когато задачите са независими?', 3),
    ('testing', 'assertions', 'ако expected стойността се получава чрез повторно извикване на същата функция със същия вход, ще открие ли тестът грешното събиране вместо умножение?', 3),
    ('testing', 'assertions', 'тест с количество 2, цена 2 и очаквана сума 4 ще открие ли замяна на умножението със събиране?', 3),
    ('postgresql', 'querying', 'ако използваме само GROUP BY по клиент и SUM на сумата, ще останат ли отделните покупки като отделни редове?', 3),
    ('postgresql', 'querying', 'ако Иван направи още една покупка за 5, колко реда за Иван ще има в резултата с такава window aggregation и каква обща сума ще стои до всеки?', 2),
    ('postgresql', 'querying', 'ако искаме последните две покупки на всеки клиент, кои номера бихме избрали?', 3),
    ('postgresql', 'querying', 'какво условие избира последните три записа за всеки клиент при същото номериране?', 3),
    ('redis', 'caching', 'ако справката липсва в кеша след изтичане, означава ли това, че е изтрита и от основната база?', 2),
    ('redis', 'caching', 'за обикновена кеширана справка, ако след успешна промяна в PostgreSQL изтрием съответния Redis ключ, какво трябва да направи приложението при следващото четене, когато ключът липсва?', 3),
    ('redis', 'caching', 'при Hash customer:42, ако се промени само limit, необходимо ли е да изпращаме отново name и notifications?', 3),
    ('kafka', 'fundamentals', 'защо приложение би изпратило събитие към Kafka, което друга услуга да обработи по-късно, вместо да извика директно нейното API?', 3),
    ('kafka', 'fundamentals', 'ако имейл услугата спре за пет минути, но Kafka работи и регистрациите успешно публикуват събитията, необходимо ли е регистрацията на нови клиенти да спре през това време?', 3),
    ('kafka', 'consumers', 'ако пуснем две копия на имейл услугата, за да си разделят работата, трябва ли да са в една и съща consumer group или в различни?', 3),
    ('kafka', 'consumers', 'каква разлика вижда потребителят между извличане на текущия баланс на един клиент и изчисляване на сумите на всички плащания по държави и месеци върху милиони записи?', 3),
    ('kafka', 'consumers', 'една или две consumer groups са нужни за независимо потребление от двете услуги?', 2),
    ('python', 'fundamentals', 'интегрирал ли е AI модел през API в Python приложение или pipeline, или досега използва само чат/IDE инструменти за помощ при разработка?', 3),
    ('ai', 'retrieval', 'помни ли потребителят дали процентът идва от векторното търсене, от самия модел или от друга библиотека?', 3),
    ('ai', 'retrieval', 'ако намереният откъс е правилен и съдържа точния отговор, възможно ли е генеративният модел все пак да даде грешен отговор?', 3),
    ('ai', 'retrieval', 'Следващ диагностичен пример без код: PDF казва срок 30 дни; в подадения откъс пише 30 дни; чатботът отговаря 14 дни. Кой етап бихме проверили първо?', 4),
    ('python', 'language_basics', 'при истинско shallow копие Б на А, ако добавим изцяло нов клиент като нов елемент само в Б, ще се появи ли той в А?', 3),
    ('python', 'language_basics', 'какъв лимит ще видим през А?', 3),
    ('python', 'fundamentals', 'Б е shallow копие на А; вместо промяна на съществуващия речник заменяме целия елемент за Иван само в Б с нов речник с лимит 300. В А първоначалният речник е с лимит 100 в този нов независим пример. Какъв лимит ще виждаме през А?', 3),
    ('python', 'language_basics', 'А сочи към текста „Иван“; присвояваме А на Б, после присвояваме на Б текста „Петър“. Какъв текст ще виждаме през А?', 3),
    ('data_engineering', 'data_pipelines', 'какъв риск има, ако освен невалидни стойности се скрие програмна грешка?', 3),
    ('data_engineering', 'data_pipelines', 'при 100 000 входни реда всички отхвърляния са очаквани и логнати, но накрая са записани само 60 000; достатъчно ли е липсата на необработено изключение да отчетем pipeline като успешен и какво друго бихме проверили?', 3),
    ('data_engineering', 'data_quality', 'скрипт отваря CSV файл и при трансформация възниква изключение преди края; как гарантира потребителят затварянето на файла и при такова прекъсване?', 3),
    ('python', 'language_basics', 'ако вътре в with open възникне ValueError и няма обработка на изключението, затварянето на файла означава ли, че програмата ще продължи нормално след блока?', 2),
    ('python', 'language_basics', 'ако извикваща функция прихване ValueError с подходящ except, може ли изпълнението да продължи след този try/except?', 3),
    ('python', 'language_basics', 'какво ще стане при извикването?', 3),
    ('python', 'language_basics', 'кои от две условия можем да решим само с текущия ред — „сума над 100 и държава България“ или „сума над средната за целия файл“?', 3),
    ('python', 'fundamentals', 'какво ще съдържа original след prepare?', 3),
    ('python', 'language_basics', 'какъв списък от грешки ще върне второто извикване и защо?', 3),
    ('python', 'language_basics', 'как би променил функцията, така че при липса на изрично подаден errors всяко извикване да започва с нов списък?', 3),
    ('python', 'language_basics', 'какво ще отпечата вторият цикъл?', 3),
    ('python', 'language_basics', 'какво отпечатва само for цикълът?', 3),
    ('python', 'fundamentals', 'a = [1, 2]; b = a.copy(); какво връща a is b и защо?', 3),
    ('python', 'language_basics', 'кога използва set вместо list в обработката на данни?', 3),
    ('python', 'language_basics', 'може ли цял Python dict за клиент да се добави директно като елемент в set, и защо?', 3),
    ('postgresql', 'performance', 'ако при изграждането на този речник има два различни записа със същия client_id и записваме последователно на същия ключ, какво ще остане като стойност?', 3),
    ('python', 'language_basics', 'при първи запис с updated_at 12:00 и втори за същия клиент с updated_at 10:00 как да предотвратим замяната на новото състояние със старото при изграждане на речника?', 3),
    ('design_patterns', 'creational', 'Следващо пояснение и въпрос: разграничаваме Factory (създаване на подходящ обект) от Adapter (съгласуване на различни интерфейси/структури). Източник A връща {"id": 42, "name": "Иван"}, а B връща {"client_id": 42, "full_name": "Иван"}. Къде потребителят би поставил преобразуването към общите полета id и name — в общата обработка или в отделния компонент за съответния източник — и защо?', 4),
    ('design_patterns', 'fundamentals', 'ако трети източник връща first_name и last_name като отделни полета, а общият формат очаква name, как би разширил подхода, за да ги обедини?', 4),
    ('design_patterns', 'fundamentals', 'какво съдържа ROW_MAPPING в предложения код — реалните стойности (например "Иван", "Петров") или имената на полетата?', 4),
    ('design_patterns', 'creational', 'след отделянето на преобразуванията в adapter за всеки източник, каква конкретна отговорност би имала Factory в първоначално предложеното решение?', 4),
    ('design_patterns', 'structural', 'Следващ теоретичен въпрос: ако всички източници трябва да изключват неактивните клиенти по едно и също бизнес правило, къде трябва да стои това правило — във всеки adapter или в общата обработка — и защо?', 3),
    ('design_patterns', 'structural', 'Следващ теоретичен сценарий: форматът на един доставчик се променя, но договореният общ формат остава същият. Коя част от системата би трябвало да се промени и какво би проверил потребителят при review?', 3),
    ('design_patterns', 'structural', 'Следващ теоретичен въпрос: ако доставчикът запази името amount, но промени стойностите от левове в стотинки, достатъчно ли е изходният формат да изглежда същият и какво трябва да направи adapter-ът?', 3),
    ('design_patterns', 'behavioral', 'Следваща концептуална проверка: ако два клиента използват едно и също правило за премахване на дубликати, нужна ли е отделна стратегия за всеки клиент или могат да споделят една?', 3),
    ('design_patterns', 'creational', 'Следващ теоретичен въпрос: има само два вида изпращачи, но на пет места в системата се повтаря логика за избора им и настройване на API клиент, credentials и timeout. Би ли помогнала Factory и какъв конкретен проблем би решила?', 3),
    ('design_patterns', 'creational', 'Следващ теоретичен сценарий: добавяне на logging и измерване на продължителността към всеки изпращач без повтаряне на тази логика във всеки от тях. Как потребителят би организирал това?', 3),
    ('design_patterns', 'creational', 'Следващ теоретичен въпрос: всеки изпращач ли ще извиква този клас, или ще има обща обвивка, която приема изпращач и изпълнява логването и измерването около неговото изпращане?', 3),
    ('design_patterns', 'structural', 'Следващ кратък теоретичен сценарий без код: един и същ изпращач трябва да може да се използва с измерване на времето или без него според средата. Как би организирал това с обсъдените подходи?', 3),
    ('design_patterns', 'behavioral', 'dashboard трябва да стартира изготвяне на отчет с една операция, без да познава отделните компоненти за четене от база, изчисляване на показатели и създаване на файл. Кой от шестте patterns е най-подходящ и защо?', 3),
    ('design_patterns', 'behavioral', 'транспортна система изчислява маршрут по най-кратко разстояние, най-бързо пристигане или най-ниска цена, като подходът може да се сменя според предпочитанието на потребителя. Кой от шестте patterns е подходящ и защо?', 3),
    ('design_patterns', 'behavioral', 'приложение работи с PostgreSQL или ClickHouse според конфигурацията; на няколко места се повтаря изборът на клиент и настройването на връзка, credentials и timeout. Кой pattern би централизирал създаването на готовия клиент?', 3),
    ('design_patterns', 'creational', 'когато наличността на продукт стане нула, отделни компоненти трябва да скрият бутона за поръчка, да уведомят склада и да обновят статистиката; нови реакции трябва да се добавят без промяна в компонента, който следи наличността. Кой pattern е подходящ и защо?', 3),
    ('design_patterns', 'structural', 'след успешно зареждане на данни независими компоненти обновяват кеш, изпращат известие и обновяват метрики; нови реакции трябва да се добавят без промяна на зареждащия компонент. Кой pattern е подходящ и защо?', 3),
    ('design_patterns', 'behavioral', 'служител стартира месечен отчет с една операция; зад нея се координират извличане на данни, изчисляване на показатели, генериране на PDF и архивиране. Искаме извикващият компонент да не познава отделните компоненти и реда на стъпките. Кой pattern е подходящ и каква отговорност ще има?', 3),
    ('design_patterns', 'behavioral', 'имаме компонент за изпращане на известия. За някои негови употреби искаме измерване на времето и логване на успех/грешка, без промяна в компонента и със същия интерфейс за извикващия. Кой pattern е подходящ и как ще се свърже с изпращача?', 3),
    ('design_patterns', 'structural', 'приложение използва локално хранилище в development и S3 в production. На няколко места се повтарят изборът и създаването на клиента с настройки за достъп и timeout. Кой pattern би помогнал и какъв конкретен проблем решава?', 3),
    ('design_patterns', 'creational', 'след уеднаквяване на входните данни система избира цена на доставка чрез фиксирана тарифа, според теглото или според разстоянието. Правилото може да се сменя, без да се променя общият процес за поръчката. Кой pattern е подходящ и какво точно е взаимозаменяемо?', 3),
    ('design_patterns', 'creational', 'два доставчика връщат статус на пратка по различен начин — единият с кодове 1/2/3, другият с текстове in_transit/delivered/returned. Системата очаква единен статус и не трябва да познава доставчика. Кой pattern е подходящ и къде трябва да остане преобразуването?', 3),
    ('design_patterns', 'behavioral', 'при списък с поръчки искаме всеки отделен ред да се запази, но до него да се показва общата стойност на поръчките за същия клиент. Какъв подход би избрал и защо обикновено GROUP BY не изпълнява сам това изискване?', 3),
    ('postgresql', 'performance', 'таблица има 10 млн. реда със status success/failed, но само 0.1% са failed; заявката търси само failed. Би ли отхвърлил индекс само заради двете възможни стойности, и защо?', 3),
    ('postgresql', 'performance', 'използвал ли е EXPLAIN или EXPLAIN ANALYZE и какво търси в резултата им, когато заявката е бавна?', 4),
    ('postgresql', 'performance', 'ако видим голяма разлика между очаквани и реални редове, достатъчно ли е веднага да заключим, че липсва индекс, или трябва да проверим и защо оценката е грешна?', 4),
    ('testing', 'assertions', 'старото правило е 10% отстъпка при сума над 100 лв., новото е 10% при сума поне 100 лв. Кои стойности би избрал, за да провериш точно промяната?', 3),
    ('airflow', 'fundamentals', 'две изпълнения едновременно проверяват едно id и двете получават „липсва“, после и двете опитват запис. Къде трябва да е гаранцията срещу дублиране?', 3),
    ('design_patterns', 'creational', 'pricing система има стандартна цена, enterprise discount, seasonal campaign, loyalty discount и custom contract pricing. Искаме лесно да сменяме начина на изчисление според customer/account context. Кой pattern е най-подходящ: Strategy, Factory или Decorator, и защо?', 3),
    ('design_patterns', 'behavioral', 'имаме importer, който чете файлове от три външни партньора. Всеки партньор подава различни имена на полета, различни status кодове и различен формат за дата, но нашата вътрешна система иска единен `OrderInput`. Кой pattern е най-подходящ: Adapter, Strategy или Facade? Къде трябва да остане преобразуването и защо?', 3),
    ('design_patterns', 'behavioral', 'след успешно създаване на order трябва независимо да се изпратят email, да се обновят analytics, да се запише audit log и да се уведоми warehouse системата. Основният order flow не трябва да знае детайлите за всяка реакция. Кой pattern е най-подходящ: Observer, Facade или Decorator? Какво е събитието и кои са observers?', 2),
    ('postgresql', 'performance', 'имаме бавна заявка към таблица `orders`, която филтрира по `status = ''paid''` и `created_at > last_24_hours`. Има отделен индекс върху `status` и отделен индекс върху `created_at`, но заявката пак е бавна. Какво би проверил преди да добавяш нов индекс, и какъв индекс би могъл да има смисъл, ако workload-ът го оправдава?', 3),
    ('postgresql', 'performance', 'ако тази заявка почти винаги търси само `status = ''paid''` за последен период, каква е разликата между composite индекс `(status, created_at)` и partial индекс върху `created_at` само за редове със `status = ''paid''`? Кой би бил по-подходящ при много чести такива заявки и защо?', 3),
    ('postgresql', 'performance', 'правиш code review на заявка, която намира последната order заявка за всеки customer чрез `ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at DESC)` и после филтрира `row_number = 1`. Какви рискове или уточнения би търсил преди да одобриш решението?', 3),
    ('airflow', 'reliability', 'task изпраща 100 batch-а. Първите 70 са приети успешно от API, batch 71 връща временна грешка, а Airflow retry стартира целия task отначало. Какъв риск има и как би направил повторението безопасно, без да дублираш вече приетите записи?', 3)
) AS v(topic_slug, subtopic_slug, question_text, difficulty)
JOIN topics t ON t.slug = v.topic_slug
JOIN subtopics s ON s.topic_id = t.id AND s.slug = v.subtopic_slug
WHERE NOT EXISTS (
    SELECT 1 FROM questions existing
    WHERE existing.subtopic_id = s.id AND lower(existing.text) = lower(v.question_text)
);

