    ('design_patterns', 'behavioral', 'имаме компонент за изпращане на известия. За някои негови употреби искаме измерване на времето и логване на успех/грешка, без промяна в компонента и със същия интерфейс за извикващия. Кой pattern е подходящ и как ще се свърже с изпращача?', 4, 3, 5, 4, 4, 4),
    ('design_patterns', 'structural', 'приложение използва локално хранилище в development и S3 в production. На няколко места се повтарят изборът и създаването на клиента с настройки за достъп и timeout. Кой pattern би помогнал и какъв конкретен проблем решава?', 4, 3, 5, 3, 4, 4),
    ('design_patterns', 'creational', 'след уеднаквяване на входните данни система избира цена на доставка чрез фиксирана тарифа, според теглото или според разстоянието. Правилото може да се сменя, без да се променя общият процес за поръчката. Кой pattern е подходящ и какво точно е взаимозаменяемо?', 4, 3, 5, 4, 4, 4),
    ('design_patterns', 'creational', 'два доставчика връщат статус на пратка по различен начин — единият с кодове 1/2/3, другият с текстове in_transit/delivered/returned. Системата очаква единен статус и не трябва да познава доставчика. Кой pattern е подходящ и къде трябва да остане преобразуването?', 4, 3, 3, 4, 4, 3),
    ('design_patterns', 'behavioral', 'при списък с поръчки искаме всеки отделен ред да се запази, но до него да се показва общата стойност на поръчките за същия клиент. Какъв подход би избрал и защо обикновено GROUP BY не изпълнява сам това изискване?', 4, 3, 5, 4, 4, 4),
    ('postgresql', 'performance', 'таблица има 10 млн. реда със status success/failed, но само 0.1% са failed; заявката търси само failed. Би ли отхвърлил индекс само заради двете възможни стойности, и защо?', 1, 3, 1, 2, 1, 1),
    ('postgresql', 'performance', 'използвал ли е EXPLAIN или EXPLAIN ANALYZE и какво търси в резултата им, когато заявката е бавна?', 1, 4, 1, 2, 1, 1),
    ('postgresql', 'performance', 'ако видим голяма разлика между очаквани и реални редове, достатъчно ли е веднага да заключим, че липсва индекс, или трябва да проверим и защо оценката е грешна?', 3, 4, 4, 3, 3, 3),
    ('testing', 'assertions', 'старото правило е 10% отстъпка при сума над 100 лв., новото е 10% при сума поне 100 лв. Кои стойности би избрал, за да провериш точно промяната?', 4, 3, 5, 3, 4, 4),
    ('airflow', 'fundamentals', 'две изпълнения едновременно проверяват едно id и двете получават „липсва“, после и двете опитват запис. Къде трябва да е гаранцията срещу дублиране?', 3, 3, 3, 3, 3, 3),
    ('design_patterns', 'creational', 'pricing система има стандартна цена, enterprise discount, seasonal campaign, loyalty discount и custom contract pricing. Искаме лесно да сменяме начина на изчисление според customer/account context. Кой pattern е най-подходящ: Strategy, Factory или Decorator, и защо?', 4, 3, 5, 4, 4, 4),
    ('design_patterns', 'behavioral', 'имаме importer, който чете файлове от три външни партньора. Всеки партньор подава различни имена на полета, различни status кодове и различен формат за дата, но нашата вътрешна система иска единен `OrderInput`. Кой pattern е най-подходящ: Adapter, Strategy или Facade? Къде трябва да остане преобразуването и защо?', 4, 3, 5, 4, 4, 4),
    ('design_patterns', 'behavioral', 'след успешно създаване на order трябва независимо да се изпратят email, да се обновят analytics, да се запише audit log и да се уведоми warehouse системата. Основният order flow не трябва да знае детайлите за всяка реакция. Кой pattern е най-подходящ: Observer, Facade или Decorator? Какво е събитието и кои са observers?', 3, 2, 4, 3, 2, 4),
    ('postgresql', 'performance', 'имаме бавна заявка към таблица `orders`, която филтрира по `status = ''paid''` и `created_at > last_24_hours`. Има отделен индекс върху `status` и отделен индекс върху `created_at`, но заявката пак е бавна. Какво би проверил преди да добавяш нов индекс, и какъв индекс би могъл да има смисъл, ако workload-ът го оправдава?', 4, 3, 5, 3, 4, 4),
    ('postgresql', 'performance', 'ако тази заявка почти винаги търси само `status = ''paid''` за последен период, каква е разликата между composite индекс `(status, created_at)` и partial индекс върху `created_at` само за редове със `status = ''paid''`? Кой би бил по-подходящ при много чести такива заявки и защо?', 4, 3, 5, 3, 4, 4),
    ('postgresql', 'performance', 'правиш code review на заявка, която намира последната order заявка за всеки customer чрез `ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at DESC)` и после филтрира `row_number = 1`. Какви рискове или уточнения би търсил преди да одобриш решението?', 3, 3, 4, 3, 3, 3),
    ('airflow', 'reliability', 'task изпраща 100 batch-а. Първите 70 са приети успешно от API, batch 71 връща временна грешка, а Airflow retry стартира целия task отначало. Какъв риск има и как би направил повторението безопасно, без да дублираш вече приетите записи?', 3, 3, 3, 3, 4, 3)
) AS v(topic_slug, subtopic_slug, question_text, score, difficulty, independence_score, clarity_score, completeness_score, confidence_score)
JOIN users u ON u.username = 'kalin'
JOIN topics t ON t.slug = v.topic_slug
JOIN subtopics s ON s.topic_id = t.id AND s.slug = v.subtopic_slug
JOIN questions q ON q.topic_id = t.id AND q.subtopic_id = s.id AND lower(q.text) = lower(v.question_text)
WHERE NOT EXISTS (
    SELECT 1 FROM answers existing
    WHERE existing.user_id = u.id AND existing.question_id = q.id
);

COMMIT;

